            var visitor = new TracingVisitorThrough();
            visitor.Visit(instance);
            var traceFromVisitor = visitor.Log;

            Assert.IsNotEmpty(traceFromVisitor);

            Assert.AreEqual(
                Our.Tests.Common.Trace(instance),
